<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/Tags.php';use Core\CacheStore;use Core\DB;use Core\Tags;$argv=isset($argv)?$argv:array();$apply=false;$limit=0;foreach(array_slice($argv,1)as $a){if($a==='--apply'){$apply=true;continue;}if(strpos($a,'--limit=')===0){$limit=max(0,(int)substr($a,8));continue;}if($a==='--dry'){$apply=false;continue;}if($a==='-h'||$a==='--help'){echo"用法: php tools/normalize_tags.php [--dry|--apply] [--limit=N]\n";exit(0);}}$pdo=DB::pdo();$people=array();try{$st=$pdo->query("SELECT item_id, name FROM person_index");foreach($st->fetchAll()as $r){$nm=trim((string)$r['name']);if($nm!==''){$people[(int)$r['item_id']][$nm]=1;}}}catch(\Throwable $e){echo"[提示] person_index 读取失败，改用 extra 中的人名做保护：{$e->getMessage()}\n";}$sql="SELECT id, genres, extra FROM media_items ORDER BY id";if($limit>0){$sql.=" LIMIT ".(int)$limit;}$rows=$pdo->query($sql)->fetchAll();$upd=$pdo->prepare("UPDATE media_items SET genres = :g WHERE id = :id");$scanned=0;$changed=0;$before=0;$after=0;$shown=0;echo $apply?"== 正式回填（写库） ==\n":"== 预演（不写库，加 --apply 才落盘） ==\n";foreach($rows as $r){$scanned++;$cur=json_decode((string)$r['genres'],true);if(!is_array($cur)){continue;}$cur=array_values(array_filter(array_map(function($a){return trim((string)$a);},$cur),'strlen'));if(empty($cur)){continue;}$before+=count($cur);$prot=isset($people[(int)$r['id']])?$people[(int)$r['id']]:array();$extra=json_decode((string)$r['extra'],true);if(!is_array($extra)){$extra=array();}foreach(CacheStore::peopleTags($extra)as $n){$n=trim((string)$n);if($n!==''){$prot[$n]=1;}}$genres=array();$keep=array();foreach($cur as $t){if(isset($prot[$t])){$keep[]=$t;}else{$genres[]=$t;}}$merged=array_values(array_unique(array_merge(Tags::normalize($genres),$keep)));$after+=count($merged);if($merged===$cur){continue;}$changed++;if(!$apply){if($shown<15){$shown++;echo sprintf("  #%d  旧: %s  →  新: %s\n",(int)$r['id'],implode('、',$cur),implode('、',$merged));}continue;}$upd->execute(array(':g'=>json_encode($merged,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),':id'=>(int)$r['id'],));if($changed%500===0){echo"  ...已处理 {$changed} 条\n";}}if($apply&&$changed>0){CacheStore::invalidateTagCaches();}echo"\n-------- 汇总 --------\n";echo"扫描条目    : {$scanned}\n";echo"需要改动    : {$changed}\n";echo"改前标签数  : {$before}\n";echo"改后标签数  : {$after}\n";echo"本次动作    : ".($apply?'已写库':'预演，未写库（加 --apply 执行）')."\n";if($apply&&$changed>0){echo"标签缓存    : 已推进版本（前台 5 分钟内刷新）\n";}echo"\n提示：先跑一次 --dry 看抽样，再跑 --apply；--apply 之后再跑一次，"."「需要改动」应为 0（幂等校验）。\n";